   set payload = '{"version": "1.0.0", "queries": [{"Query": {"Commands": [{"SemanticQueryDataShapeCommand": {"Query": {"Version": 2, "From": [{"Name": "e", "Entity": "evtencerramento", "Type": 0}, {"Name": "a", "Entity": "abccc ANIMA_PR", "Type": 0}, {"Name": "e1", "Entity": "evtprova", "Type": 0}, {"Name": "e2", "Entity": "evtclassificacao_inscrito", "Type": 0}, {"Name": "a1", "Entity": "abccc ANIMA", "Type": 0}, {"Name": "a2", "Entity": "abccc ANIMA (2)", "Type": 0}, {"Name": "a3", "Entity": "abccc PESSOAS", "Type": 0}], "Select": [{"Column": {"Expression": {"SourceRef": {"Source": "e"}}, "Property": "sbb"}, "Name": "evtencerramento.sbb", "NativeReferenceName": "SBB"}, {"Column": {"Expression": {"SourceRef": {"Source": "a"}}, "Property": "DAD_DESCRI"}, "Name": "abccc ANIMA_PR.DAD_DESCRI", "NativeReferenceName": "Animal"}, {"Column": {"Expression": {"SourceRef": {"Source": "e1"}}, "Property": "descricao"}, "Name": "evtprova.descricao", "NativeReferenceName": "Prova"}, {"Column": {"Expression": {"SourceRef": {"Source": "e"}}, "Property": "ciclo"}, "Name": "evtencerramento.ciclo", "NativeReferenceName": "Ciclo"}, {"Column": {"Expression": {"SourceRef": {"Source": "e"}}, "Property": "cidade"}, "Name": "evtencerramento.cidade", "NativeReferenceName": "Cidade"}, {"Column": {"Expression": {"SourceRef": {"Source": "a1"}}, "Property": "DAD_DESCRI"}, "Name": "abccc ANIMA.DAD_DESCRI", "NativeReferenceName": "Pai"}, {"Column": {"Expression": {"SourceRef": {"Source": "a2"}}, "Property": "DAD_DESCRI"}, "Name": "abccc ANIMA (2).DAD_DESCRI", "NativeReferenceName": "M\u00e3e"}, {"Column": {"Expression": {"SourceRef": {"Source": "a3"}}, "Property": "DAD_DESCRI"}, "Name": "abccc PESSOAS.DAD_DESCRI", "NativeReferenceName": "Criador"}, {"Column": {"Expression": {"SourceRef": {"Source": "e"}}, "Property": "SexoNome"}, "Name": "evtencerramento.SexoNome", "NativeReferenceName": "Sexo"}, {"Column": {"Expression": {"SourceRef": {"Source": "e2"}}, "Property": "Premio_Generico"}, "Name": "e